"AIbHfryMA2Rvs1ut": {"id":"AIbHfryMA2Rvs1ut","name":"Banish","domain":"codex","level":6,"cardType":"spell","description":"Make a Spellcast Roll against a target within Close range. On a success, roll a number of d20 s equal to your Spellcast trait. The target must make a reaction roll with a Difficulty equal to your highest result. On a success, the target must mark a Stress but isn't banished. Once per rest on a failure, they are banished from this realm. When the PCs roll with Fear, the Difficulty gains a -1 penalty and the target makes another reaction roll. On a success, they return from banishment.","actions":[{"name":"Spellcast Roll","type":"attack","roll":"spellcast","target":"any","amount":1,"range":"close","parts":[],"effects":[],"areas":[]}]},
