"eq8VNqYMRHhF9xw9": {"id":"eq8VNqYMRHhF9xw9","name":"Book of Sitil","domain":"codex","level":2,"cardType":"grimoire","description":"Adjust Appearance: You magically shift your appearance and clothing to avoid recognition. Parallela: Spend 2 Hope to cast this spell on yourself or an ally within Close range. The next time the target makes an attack, they can hit an additional target within range that their attack roll would succeed against. You can only hold this spell on one creature at a time. Illusion: Make a Spellcast Roll (14). On a success, create a temporary visual illusion no larger than you within Close range that lasts for as long as you look at it. It holds up to scrutiny until an observer is within Melee range.","actions":[{"name":"Adjust Appearance","type":"effect","roll":null,"target":"self","amount":null,"range":"self","parts":[],"effects":[{"name":"Adjust Appearance","statuses":[]}],"areas":[]},{"name":"Parallela","type":"effect","roll":null,"target":"friendly","amount":1,"range":"close","parts":[],"effects":[{"name":"Parallela","statuses":[]}],"areas":[]},{"name":"Illusion","type":"attack","roll":"spellcast","target":"any","amount":null,"range":"close","parts":[],"effects":[],"areas":[]}]},
